export default async () => {
  const iconB64 = "";

  let bodyContent = "";
  try {
    const resp = await fetch("https://claude.ai/code/artifact/aaca4b18-536d-42c3-bba9-26da26f6e24b");
    const html = await resp.text();
    const titleIdx = html.indexOf("<title>");
    bodyContent = titleIdx >= 0 ? html.slice(titleIdx) : html;
  } catch (err) {
    bodyContent = "<p style='font-family:sans-serif;padding:40px;'>読み込みに失敗しました。時間をおいて再度お試しください。</p>";
  }

  const finalHtml = `<!DOCTYPE html>
<html lang="ja">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
<title>競合ウォッチ | WILLOW'S</title>
<link rel="apple-touch-icon" href="data:image/jpeg;base64,${iconB64}">
<link rel="icon" href="data:image/jpeg;base64,${iconB64}">
</head>
<body>
${bodyContent}
</body>
</html>`;

  return new Response(finalHtml, {
    headers: { "content-type": "text/html; charset=utf-8" }
  });
};

export const config = { path: ["/competitor-watch", "/competitor-watch/"] };
